/**
 * T10 — the font runtime: `src/core/font-data.ts` turned into a texture and a `Container`.
 *
 * There is no font file to load, so the atlas is *built* on first use: one canvas, one
 * row of `CELL_WIDTH x CELL_HEIGHT` cells, white ink on transparent, uploaded once and
 * sliced into a `Texture` per glyph. White is deliberate — every colour the UI uses is a
 * sprite `tint`, which costs nothing and means `d.n()`'s `setColor(16777214)` and the
 * banner's own colour are one texture between them.
 *
 * `BitmapText` is the drawing surface. It keeps a pool of glyph sprites and rewrites them
 * in place, because the HUD's score line changes on a tick where a crystal is taken and
 * would otherwise churn a `Container` of eight sprites every time.
 *
 * The layout half — `measureText`, `wrapText` — is free of Pixi and of the DOM so the
 * suites can check the wrap without a canvas.
 */
import { Container, Rectangle, Sprite, Texture } from 'pixi.js';

import {
  ADVANCE,
  CELL_HEIGHT,
  CELL_WIDTH,
  LINE_HEIGHT,
  glyphBitmap,
  supportedCharacters,
} from './font-data.ts';

export { ADVANCE, CELL_HEIGHT, CELL_WIDTH, LINE_HEIGHT } from './font-data.ts';

/** Width in pixels of a single line. Monospace, so it is just a multiplication. */
export function measureText(text: string): number {
  const length = [...text].length;
  // The trailing pixel of inter-glyph gap is not part of the drawn width.
  return length === 0 ? 0 : length * ADVANCE - (ADVANCE - CELL_WIDTH);
}

/** How many whole glyphs fit in `width` pixels. */
export function charsPerLine(width: number): number {
  return Math.max(1, Math.floor((width + (ADVANCE - CELL_WIDTH)) / ADVANCE));
}

/**
 * Greedy word wrap at `width` pixels, honouring the newlines already in the string.
 * A word longer than the line is hard-broken rather than allowed to run off the screen —
 * `Instructions` in Hungarian has several.
 */
export function wrapText(text: string, width: number): string[] {
  const columns = charsPerLine(width);
  const lines: string[] = [];

  for (const paragraph of text.split('\n')) {
    let line = '';
    for (const word of paragraph.split(' ')) {
      let rest = word;
      while (rest.length > columns) {
        if (line.length > 0) {
          lines.push(line);
          line = '';
        }
        lines.push(rest.slice(0, columns));
        rest = rest.slice(columns);
      }
      if (line.length === 0) line = rest;
      else if (line.length + 1 + rest.length <= columns) line += ` ${rest}`;
      else {
        lines.push(line);
        line = rest;
      }
    }
    lines.push(line);
  }

  return lines;
}

/** Total height of `lines` rendered one under the other. */
export function textBlockHeight(lines: number): number {
  return lines === 0 ? 0 : (lines - 1) * LINE_HEIGHT + CELL_HEIGHT;
}

/**
 * Texels per layout pixel in the built atlas — PLAN-HD H3.5's second slice site.
 *
 * `CELL_WIDTH` and `CELL_HEIGHT` are *layout* constants: `measureText`, `wrapText` and
 * `tests/states.test.ts` are all denominated in them and none of them may move. What can
 * move is how many texels stand behind one of those units, and that is this number.
 *
 * One today, because `font-data.ts` is a 5x9 bitmap and the atlas is that bitmap
 * replicated. H5 is what raises it: it swaps `glyphBitmap`'s squares for traced outlines
 * at 8, and because the frame rectangle below is expressed in layout units and divided by
 * `source.resolution`, that is the only place H5 has to touch here. No `* 8` at any call
 * site, and the same drawing code serves both densities.
 */
const DENSITY = 1;

/**
 * The built atlas. One instance for the process; `BitmapText` reaches for it lazily so a
 * test that only imports the layout helpers never touches a canvas.
 */
export class BitmapFont {
  private static instance: BitmapFont | null = null;

  private readonly textures = new Map<string, Texture>();

  private readonly fallback: Texture;

  private constructor() {
    const characters = supportedCharacters();
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, (characters.length + 1) * CELL_WIDTH * DENSITY);
    canvas.height = CELL_HEIGHT * DENSITY;

    const context = canvas.getContext('2d');
    if (!context) throw new Error('no 2d context for the bitmap font');
    const image = context.createImageData(canvas.width, canvas.height);

    // The box glyph goes in cell 0, so an unmapped character has somewhere to point.
    const cells = ['', ...characters];
    cells.forEach((ch, index) => {
      glyphBitmap(ch).forEach((row, y) => {
        for (let x = 0; x < CELL_WIDTH; x++) {
          if (row[x] !== '1') continue;
          const left = (index * CELL_WIDTH + x) * DENSITY;
          const top = y * DENSITY;
          for (let ty = top; ty < top + DENSITY; ty++) {
            for (let tx = left; tx < left + DENSITY; tx++) {
              const offset = (ty * canvas.width + tx) * 4;
              image.data[offset] = 0xff;
              image.data[offset + 1] = 0xff;
              image.data[offset + 2] = 0xff;
              image.data[offset + 3] = 0xff;
            }
          }
        }
      });
    });
    context.putImageData(image, 0, 0);

    const source = Texture.from(canvas).source;
    // `resolution` is what keeps the cell rectangle below in layout units: Pixi divides a
    // frame by it, so a glyph is CELL_WIDTH x CELL_HEIGHT whatever DENSITY is.
    source.resolution = DENSITY;
    source.scaleMode = 'nearest';
    // The cells abut, so a filtered sample would bleed a neighbour's ink into the edge.
    source.label = 'bitmap-font';

    const cell = (index: number): Texture =>
      new Texture({
        source,
        frame: new Rectangle(index * CELL_WIDTH, 0, CELL_WIDTH, CELL_HEIGHT),
      });

    this.fallback = cell(0);
    cells.forEach((ch, index) => {
      if (index > 0) this.textures.set(ch, cell(index));
    });
  }

  static shared(): BitmapFont {
    BitmapFont.instance ??= new BitmapFont();
    return BitmapFont.instance;
  }

  textureFor(ch: string): Texture {
    return this.textures.get(ch) ?? this.fallback;
  }
}

export type BitmapTextOptions = {
  /** Sprite tint. `d.n()` draws its strings in `16777214`; that is the default. */
  colour?: number;
  /** `0` left, `0.5` centred, `1` right — applied per line about the text's own x. */
  align?: number;
};

/** `d.n()`'s `drawString`: one line, or several separated by `\n`. */
export class BitmapText extends Container {
  private readonly sprites: Sprite[] = [];

  private readonly font = BitmapFont.shared();

  private value = '';

  private colour: number;

  private readonly align: number;

  constructor(text = '', options: BitmapTextOptions = {}) {
    super();
    this.colour = options.colour ?? 0xfffffe;
    this.align = options.align ?? 0;
    this.text = text;
  }

  get text(): string {
    return this.value;
  }

  set text(next: string) {
    if (next === this.value) return;
    this.value = next;
    this.rebuild();
  }

  get tintColour(): number {
    return this.colour;
  }

  set tintColour(next: number) {
    if (next === this.colour) return;
    this.colour = next;
    for (const sprite of this.sprites) sprite.tint = next;
  }

  /** Width of the widest line. */
  get textWidth(): number {
    return this.value.split('\n').reduce((widest, line) => Math.max(widest, measureText(line)), 0);
  }

  get textHeight(): number {
    return textBlockHeight(this.value.split('\n').length);
  }

  private rebuild(): void {
    let used = 0;
    this.value.split('\n').forEach((line, row) => {
      const offset = Math.round(-measureText(line) * this.align);
      [...line].forEach((ch, column) => {
        if (ch === ' ') return;
        let sprite = this.sprites[used];
        if (!sprite) {
          sprite = new Sprite();
          this.sprites.push(sprite);
          this.addChild(sprite);
        }
        used++;
        sprite.texture = this.font.textureFor(ch);
        sprite.tint = this.colour;
        sprite.visible = true;
        sprite.position.set(offset + column * ADVANCE, row * LINE_HEIGHT);
      });
    });
    for (let i = used; i < this.sprites.length; i++) this.sprites[i]!.visible = false;
  }
}
