/**
 * T10 — the 32-pixel strip under the play area, transcribed from `d.n()`.
 *
 * ```java
 * if (this.C) {                                  // the dirty flag
 *     this.ad.setColor(545706);                  // 0x0853AA
 *     this.ad.fillRect(0, 97, 128, 32);
 *     for (int i = 0; i < this.j; i++)           // lives
 *         this.ad.drawImage(this.D, 5 + i * (this.D.getWidth() - 1), 99, 20);
 *     for (int i2 = 0; i2 < this.ay - this.aa; i2++)   // hoops left
 *         this.ad.drawImage(this.G, 5 + i2 * (this.G.getWidth() - 4), 112, 20);
 *     this.ad.setColor(16777214);                // 0xFFFFFE
 *     this.ad.setFont(this.ae);
 *     this.ad.drawString(c(this.g), 64, 100, 20);      // score
 *     if (this.al != 0) {                              // the boost meter
 *         this.ad.setColor(16750611);                  // 0xFF9613
 *         this.ad.fillRect(1, 128 - 3 * this.al / 30, 5, 128);
 *     }
 *     this.C = false;
 * }
 * ```
 *
 * Four things are worth pulling out of that:
 *
 * - **The strip starts at y=97, not 96.** `b.H` is 96 tall and drawn at the top, so row 96
 *   is the one pixel of whatever the 128x128 buffer already held — in practice the frame's
 *   own clear. The port leaves it alone for the same reason.
 * - **`D` and `G` are 12px sprites drawn 11 and 8 apart.** So the lives overlap by a pixel
 *   and the hoop pips by four. Both are `b.a(Image,int,int)` cuts of the sheet, and T2
 *   named them `hud_life` and `hud_hoop`.
 * - **The `fillRect` for the meter is `(1, y, 5, 128)`** — MIDP's `fillRect` takes a width
 *   and a height, so that is a 5x128 rectangle starting at `y`, i.e. it runs 128 pixels
 *   *past* the strip and is clipped by the screen. It reads as "a bar growing upward from
 *   the bottom", 30px tall at a full 300-tick boost, and that is what it draws.
 * - **`al` is the *largest* of the three boost timers**, not their sum, and `d.a()` only
 *   marks the HUD dirty every 30 ticks, so the bar visibly steps rather than sliding.
 *   Redrawing every frame here is free and looks the same at 25 Hz.
 *
 * The banner (`Level %U`, `drawString(this.S, 44, 84, 20)`) belongs to `paint`, not to
 * `n()`, so it is drawn over the play area rather than in the strip — but it is the only
 * other text the canvas has, so it lives here too.
 */
import { Container, Graphics, Sprite, type Spritesheet } from 'pixi.js';

import { BitmapText } from '../core/BitmapFont.ts';
import { VIEW_HEIGHT, VIEW_WIDTH } from './Camera.ts';
import { HUD_COLOUR } from './Tiles.ts';

/** `d.n()`'s `fillRect(0, 97, 128, 32)` — one row below the 96px play area. */
export const HUD_TOP = VIEW_HEIGHT + 1;

/** `setColor(16777214)`. Not `0xFFFFFF`; the original is one short of white. */
export const TEXT_COLOUR = 0xfffffe;

/** `setColor(16750611)` — the boost meter. */
export const METER_COLOUR = 0xff9613;

/** `5 + i * (D.getWidth() - 1)` and `y = 99`. */
export const LIVES_X = 5;
export const LIVES_Y = 99;
export const LIVES_STEP = 11;

/** `5 + i * (G.getWidth() - 4)` and `y = 112`. */
export const HOOPS_X = 5;
export const HOOPS_Y = 112;
export const HOOPS_STEP = 8;

/** `drawString(c(this.g), 64, 100, TOP | LEFT)`. */
export const SCORE_X = 64;
export const SCORE_Y = 100;

/** `drawString(this.S, 44, 84, TOP | LEFT)` — the `Level %U` banner over the play area. */
export const BANNER_X = 44;
export const BANNER_Y = 84;

/** The meter's box: `fillRect(1, y, 5, ...)`, growing up from the bottom of the screen. */
export const METER_X = 1;
export const METER_WIDTH = 5;

/** `128 - 3 * al / 30` with `al` at its 300-tick maximum. */
export const METER_MAX_HEIGHT = 30;

/** `d.al`'s ceiling — `BOOST_TICKS`, the value the three boosts are set to. */
const METER_FULL = 300;

/**
 * `d.c(int)` — the score, left-padded with zeroes.
 *
 * The padding table is the original's, and it is **inconsistent**: scores under 100 get
 * seven zeroes, so 5 prints as eight characters and 99 as nine, while everything from 100
 * up prints as exactly eight. Reproduced rather than corrected — it is on screen for the
 * first few seconds of every game.
 */
export function formatScore(score: number): string {
  const value = Math.max(0, Math.trunc(score));
  let pad: string;
  if (value < 100) pad = '0000000';
  else if (value < 1000) pad = '00000';
  else if (value < 10000) pad = '0000';
  else if (value < 100000) pad = '000';
  else if (value < 1000000) pad = '00';
  else if (value < 10000000) pad = '0';
  else pad = '';
  return pad + value;
}

/** `d.al` — the longest-running of the three boosts, or 0 when none is running. */
export function meterTicks(speed: number, gravity: number, jump: number): number {
  return Math.max(0, speed, gravity, jump);
}

/** The meter's top edge in screen pixels: `128 - 3 * al / 30`, integer division. */
export function meterTop(ticks: number): number {
  return 128 - Math.trunc((3 * Math.min(ticks, METER_FULL)) / 30);
}

export type HudState = {
  score: number;
  lives: number;
  /** `d.ay - d.aa` — hoops still to collect. */
  hoopsLeft: number;
  /** `d.al`, already reduced by `meterTicks`. */
  boostTicks: number;
  /** `d.r` — while non-zero the `Level %U` banner is drawn. */
  bannerTicks: number;
};

/**
 * The strip and the banner. `view` goes above the play area's containers and below
 * nothing; `d.n()` draws the HUD into the same buffer after the tiles and the ball.
 */
export class Hud {
  readonly view = new Container();

  private readonly strip = new Graphics();

  private readonly lives: Sprite[] = [];

  private readonly hoops: Sprite[] = [];

  private readonly livesLayer = new Container();

  private readonly hoopsLayer = new Container();

  private readonly meter = new Graphics();

  private readonly score = new BitmapText('', { colour: TEXT_COLOUR });

  private readonly banner = new BitmapText('', { colour: TEXT_COLOUR });

  private readonly sheet: Spritesheet;

  /** `b.S`, already through `I18n` — the banner is the level name, fixed for the level. */
  bannerText = '';

  constructor(sheet: Spritesheet) {
    this.sheet = sheet;

    this.strip.rect(0, HUD_TOP, VIEW_WIDTH, 128 - HUD_TOP).fill(HUD_COLOUR);
    this.score.position.set(SCORE_X, SCORE_Y);
    this.banner.position.set(BANNER_X, BANNER_Y);

    this.view.addChild(
      this.strip,
      this.livesLayer,
      this.hoopsLayer,
      this.score,
      this.meter,
      this.banner,
    );

    // Level 011 has fourteen hoops, and `5 + 13 * 8 + 12` is 121 — but eleven lives would
    // run off the edge, and so would a translated banner. MIDP clips to the `Canvas`;
    // outside the 128x128 area there is only letterbox, so clip here too.
    const clip = new Graphics().rect(0, 0, VIEW_WIDTH, 128).fill(0xffffff);
    this.view.addChild(clip);
    this.view.mask = clip;
  }

  update(state: HudState): void {
    this.score.text = formatScore(state.score);

    this.fill(
      this.lives,
      this.livesLayer,
      'hud_life',
      Math.max(0, state.lives),
      LIVES_X,
      LIVES_Y,
      LIVES_STEP,
    );
    this.fill(
      this.hoops,
      this.hoopsLayer,
      'hud_hoop',
      Math.max(0, state.hoopsLeft),
      HOOPS_X,
      HOOPS_Y,
      HOOPS_STEP,
    );

    this.meter.clear();
    if (state.boostTicks !== 0) {
      const top = meterTop(state.boostTicks);
      this.meter.rect(METER_X, top, METER_WIDTH, 128 - top).fill(METER_COLOUR);
    }

    this.banner.text = state.bannerTicks !== 0 ? this.bannerText : '';
  }

  private fill(
    pool: Sprite[],
    layer: Container,
    frame: string,
    count: number,
    x: number,
    y: number,
    step: number,
  ): void {
    for (let i = 0; i < count; i++) {
      let sprite = pool[i];
      if (!sprite) {
        const texture = this.sheet.textures[frame];
        if (!texture) throw new Error(`atlas frame "${frame}" is missing`);
        sprite = new Sprite(texture);
        pool.push(sprite);
        layer.addChild(sprite);
      }
      sprite.visible = true;
      sprite.position.set(x + i * step, y);
    }
    for (let i = count; i < pool.length; i++) pool[i]!.visible = false;
  }
}
