/**
 * T12 — the responsive geometry, with no renderer in it.
 *
 * `Viewport` and `TouchPad` are Pixi objects and cannot be constructed in node, but the
 * arithmetic they carry out is the whole of T12's "responsive" and "touch controls"
 * acceptance criteria: which scale a 390x844 phone gets, where the control band sits, how
 * big a thumb target is, which button a tap at (x, y) presses. All of it is a pure
 * function of a window size, and lives here so `tests/platform.test.ts` can check a phone,
 * a tablet and a 4K desktop without a canvas.
 *
 * Coordinates come in two spaces and the distinction matters:
 *
 * - **virtual pixels** — the 128x128 the game is drawn in, `b.ao` x `b.aw`. Everything
 *   `game/` and `states/` works in.
 * - **CSS pixels** — the canvas's own space, which the layout and the touch pad work in.
 *   A thumb target is 44 CSS px because that is a finger; it is 22 virtual pixels at 2x
 *   and 7 at 6x, which is why the buttons are not drawn in the game's space.
 *
 * Device pixels appear once, in `integer` fit, where the whole point is to land on them.
 */
import type { Action } from './Input';
import type { FitMode } from './Platform';

/** `b.ao` — the `FullCanvas` width. */
export const VIEW_WIDTH = 128;

/** `b.aw` — the `FullCanvas` height. */
export const VIEW_HEIGHT = 128;

/**
 * Height of the play area: `b.H = Image.createImage(156, 96)`. The remaining 32px are the
 * HUD strip class `d` paints at y=99 (lives) and y=112 (hoops).
 */
export const PLAY_HEIGHT = 96;

export type Rect = { x: number; y: number; w: number; h: number };

export type Insets = { top: number; right: number; bottom: number; left: number };

export const NO_INSETS: Insets = { top: 0, right: 0, bottom: 0, left: 0 };

export type Orientation = 'portrait' | 'landscape';

/**
 * The two halves of the control band: steering on the left, the bounce on the right. In
 * portrait they are the two halves of the bottom strip, in landscape the two side strips.
 */
export type PadRegions = { orientation: Orientation; left: Rect; right: Rect };

export type LayoutInput = {
  /** Renderer size in CSS pixels. */
  cssWidth: number;
  cssHeight: number;
  /** `renderer.resolution`, i.e. device pixels per CSS pixel. */
  resolution: number;
  /** Virtual size to fit. 128x128 unless widescreen widens the first. */
  viewWidth?: number;
  viewHeight?: number;
  fit?: FitMode;
  /** Reserve room for the touch pad. */
  controls?: boolean;
  insets?: Insets;
};

export type ViewportMetrics = {
  /** CSS pixels per virtual pixel. Non-integer on a HiDPI display, by design. */
  scale: number;
  /** Device pixels per virtual pixel. A whole number in `integer` fit; that is the point. */
  deviceScale: number;
  /** Offset of the drawn area's top-left inside the canvas, in CSS pixels. */
  offsetX: number;
  offsetY: number;
  viewWidth: number;
  viewHeight: number;
  fit: FitMode;
  orientation: Orientation;
  /** Where `TouchPad` may draw, in CSS pixels. `null` when controls are off. */
  pad: PadRegions | null;
};

/**
 * Portrait band height, as a fraction of the safe height and clamped. A thumb needs about
 * 44 CSS px of target plus room to miss; 96 is two of those side by side with margins.
 */
const PORTRAIT_BAND_FRACTION = 0.26;
const PORTRAIT_BAND_MIN = 96;
const PORTRAIT_BAND_MAX = 220;

/** Landscape side strips. Same reasoning, measured across instead of down. */
const LANDSCAPE_SIDE_FRACTION = 0.2;
const LANDSCAPE_SIDE_MIN = 110;
const LANDSCAPE_SIDE_MAX = 220;

/** Never shrink the game box below this to make room for buttons. */
const MIN_GAME_BOX = 64;

function clamp(value: number, low: number, high: number): number {
  return Math.min(high, Math.max(low, value));
}

/**
 * The whole of the responsive behaviour, as a pure function: no DOM, no Pixi, so
 * `tests/platform.test.ts` can check a phone, a tablet and a 4K desktop without one.
 */
export function computeLayout(input: LayoutInput): ViewportMetrics {
  const viewWidth = Math.max(1, input.viewWidth ?? VIEW_WIDTH);
  const viewHeight = Math.max(1, input.viewHeight ?? VIEW_HEIGHT);
  const fit: FitMode = input.fit ?? 'integer';
  const resolution = input.resolution > 0 ? input.resolution : 1;
  const insets = input.insets ?? NO_INSETS;

  // The window minus anything the OS draws over.
  const area: Rect = {
    x: insets.left,
    y: insets.top,
    w: Math.max(1, input.cssWidth - insets.left - insets.right),
    h: Math.max(1, input.cssHeight - insets.top - insets.bottom),
  };

  const orientation: Orientation = area.w >= area.h ? 'landscape' : 'portrait';

  let game: Rect = area;
  let pad: PadRegions | null = null;

  if (input.controls) {
    if (orientation === 'portrait') {
      const band = Math.min(
        clamp(area.h * PORTRAIT_BAND_FRACTION, PORTRAIT_BAND_MIN, PORTRAIT_BAND_MAX),
        Math.max(0, area.h - MIN_GAME_BOX),
      );
      game = { x: area.x, y: area.y, w: area.w, h: area.h - band };
      const strip: Rect = { x: area.x, y: area.y + area.h - band, w: area.w, h: band };
      pad = {
        orientation,
        left: { x: strip.x, y: strip.y, w: strip.w / 2, h: strip.h },
        right: { x: strip.x + strip.w / 2, y: strip.y, w: strip.w / 2, h: strip.h },
      };
    } else {
      const side = Math.min(
        clamp(area.w * LANDSCAPE_SIDE_FRACTION, LANDSCAPE_SIDE_MIN, LANDSCAPE_SIDE_MAX),
        Math.max(0, (area.w - MIN_GAME_BOX) / 2),
      );
      game = { x: area.x + side, y: area.y, w: area.w - 2 * side, h: area.h };
      pad = {
        orientation,
        left: { x: area.x, y: area.y, w: side, h: area.h },
        right: { x: area.x + area.w - side, y: area.y, w: side, h: area.h },
      };
    }
  }

  // The largest scale that fits the game box, before any rounding.
  const exact = Math.min(game.w / viewWidth, game.h / viewHeight);

  let scale: number;
  let deviceScale: number;
  if (fit === 'integer') {
    // Whole device pixels per virtual pixel, and never below 1 — a window too small for
    // 1x clips rather than blurs, which is the lesser of the two.
    deviceScale = Math.max(1, Math.floor(exact * resolution));
    scale = deviceScale / resolution;
  } else {
    scale = Math.max(exact, 1 / resolution);
    deviceScale = scale * resolution;
  }

  // Centre in the game box. In `integer` fit the offset is snapped to whole device pixels
  // too, or the crisp upscale lands on a half-pixel boundary and smears anyway.
  const rawX = game.x + (game.w - viewWidth * scale) / 2;
  const rawY = game.y + (game.h - viewHeight * scale) / 2;
  const offsetX = fit === 'integer' ? Math.floor(rawX * resolution) / resolution : rawX;
  const offsetY = fit === 'integer' ? Math.floor(rawY * resolution) / resolution : rawY;

  return { scale, deviceScale, offsetX, offsetY, viewWidth, viewHeight, fit, orientation, pad };
}

export type PadGlyph = 'left' | 'right' | 'up';

export type PadButton = {
  action: Action;
  glyph: PadGlyph;
  cx: number;
  cy: number;
  r: number;
};

/** Extra hit radius, as a fraction of the drawn one. */
export const HIT_SLOP = 1.3;

/** Steering buttons: two of them share a region, so they get less of it. */
const STEER_MIN_R = 20;
const STEER_MAX_R = 46;

/** The bounce button has its region to itself and is the one you press most. */
const JUMP_MIN_R = 24;
const JUMP_MAX_R = 58;

/** Keep the buttons off the very edge of the glass, where a palm rests. */
const EDGE_PAD = 10;

/** Space between the two steering buttons, as a fraction of their radius. */
const STEER_GAP = 0.45;

/**
 * Width the pair needs: two diameters plus the gap. Inverting it is how the radius is
 * chosen, so `padButtons()` fits its region by construction rather than by luck — the one
 * exception being a region too narrow even for `STEER_MIN_R`, where a reachable button
 * that overhangs beats a correct one nobody can hit.
 */
const STEER_SPAN = 4 + STEER_GAP;

/**
 * Two steering buttons side by side, centred in `region`: the bottom-left quarter of the
 * screen in portrait, the left-hand strip in landscape, which is where a left thumb is.
 */
function steerButtons(region: Rect, orientation: PadRegions['orientation']): PadButton[] {
  const r = clamp(
    Math.min((region.w - 2 * EDGE_PAD) / STEER_SPAN, (region.h - 2 * EDGE_PAD) / 2),
    STEER_MIN_R,
    STEER_MAX_R,
  );
  const gap = r * STEER_GAP;
  // Portrait's band is short and wide, so the pair sits in the middle of it; landscape's
  // strip is tall, so they sit at the bottom, under the thumb rather than under the eye.
  const cy =
    orientation === 'portrait' ? region.y + region.h / 2 : region.y + region.h - r - EDGE_PAD;
  const centre = region.x + region.w / 2;

  return [
    { action: 'LEFT', glyph: 'left', cx: centre - r - gap / 2, cy, r },
    { action: 'RIGHT', glyph: 'right', cx: centre + r + gap / 2, cy, r },
  ];
}

/** One bounce button, centred across `region` and, in landscape, low in it. */
function jumpButton(region: Rect, orientation: PadRegions['orientation']): PadButton {
  const r = clamp(
    Math.min((region.w - 2 * EDGE_PAD) / 2, (region.h - 2 * EDGE_PAD) / 2),
    JUMP_MIN_R,
    JUMP_MAX_R,
  );
  const cx = region.x + region.w / 2;
  const cy =
    orientation === 'portrait' ? region.y + region.h / 2 : region.y + region.h - r - EDGE_PAD;
  return { action: 'UP', glyph: 'up', cx, cy, r };
}

/** The three buttons for a pad layout, in CSS pixels. Pure; see the suite. */
export function padButtons(pad: PadRegions): PadButton[] {
  return [...steerButtons(pad.left, pad.orientation), jumpButton(pad.right, pad.orientation)];
}

/** Which button a canvas-space point presses, slop included. */
export function hitButton(
  buttons: readonly PadButton[],
  x: number,
  y: number,
): PadButton | undefined {
  let best: PadButton | undefined;
  let bestDistance = Infinity;
  for (const button of buttons) {
    const dx = x - button.cx;
    const dy = y - button.cy;
    const distance = Math.hypot(dx, dy);
    // Nearest wins, so two overlapping slop circles still resolve the way a thumb means.
    if (distance <= button.r * HIT_SLOP && distance < bestDistance) {
      best = button;
      bestDistance = distance;
    }
  }
  return best;
}
