/**
 * T6/T12 — the 128x128 screen, replacing `com.nokia.mid.ui.FullCanvas`.
 *
 * `b.a()` reads `getWidth()`/`getHeight()` into `b.ao`/`b.aw`, and on the handset a
 * `FullCanvas` is the whole 128x128 display — no title bar, no soft-key strip. Class `d`
 * hard-codes coordinates against that: the splash is centred at `(ao >> 1, aw >> 1)`,
 * the level buffer `b.H` is 96px tall, and the HUD sits at y=99 and y=112. Everything the
 * port draws therefore lives in a 128x128 coordinate space, and this class is the only
 * place that knows how that space maps to the browser window.
 *
 * ## T12: two fits, a reserved band, and a wider stage
 *
 * **`integer`** is T6's mapping and the parity path: an integer upscale *measured in
 * device pixels*, letterboxed on black. Integer-in-device-pixels is the part that
 * matters: with `resolution = devicePixelRatio` a container scale of, say, 2 on a 3x phone
 * puts virtual pixels on 6 device pixels (fine), but a scale chosen from CSS pixels can
 * land on 2.5, and half a device pixel of bilinear smear is exactly the blur `nearest` was
 * meant to avoid. So the scale is picked from the device-pixel budget and divided back
 * down, and the letterbox offset is snapped to whole device pixels too.
 *
 * **`contain`** is the phone fit: the largest scale that fits, fractional. On a 390x844
 * screen `integer` gives 2x — a 256px square in the middle of a phone — where `contain`
 * gives 3.05x and fills the width. The upscale is still `nearest`, so the cost is not
 * blur but uneven pixels (some virtual pixels one device pixel wider than their
 * neighbours), which at 3x is invisible and at 2x would not be. Desktop defaults to
 * `integer`, touch to `contain`; `?fit=` overrides. See `core/Platform`.
 *
 * **The reserved band** is where T12's on-screen buttons go, and the reason `layout()`
 * does not simply centre in the window: PLAN.md §T12 asks for the buttons *outside* the
 * play area, so the game box is the window minus a strip (below in portrait, one either
 * side in landscape) and `TouchPad` draws into what is left. Safe-area insets come off
 * first, so nothing lands under a notch or a home indicator.
 *
 * **Widescreen** widens the drawn area past 128 (`?wide`). `root` then spans
 * `viewWidth x 128` and `screen` — where every 128-wide screen draws — is inset by
 * `contentOffsetX` so menus and the HUD stay centred. Only `PlayState` uses the extra
 * width, by drawing its band at `-contentOffsetX` in its own view. It is not parity and
 * says so.
 */
import { Container, type Application } from 'pixi.js';

import type { FitMode } from './Platform';

import { VIEW_WIDTH, computeLayout, type Insets, type ViewportMetrics } from './Layout';

export {
  NO_INSETS,
  PLAY_HEIGHT,
  VIEW_HEIGHT,
  VIEW_WIDTH,
  computeLayout,
  type Insets,
  type LayoutInput,
  type Orientation,
  type PadRegions,
  type Rect,
  type ViewportMetrics,
} from './Layout';

export type ViewportOptions = {
  fit?: FitMode;
  controls?: boolean;
  /** Virtual width of the drawn area; > 128 only in widescreen. */
  viewWidth?: number;
  /** Reads the current safe-area insets. Defaults to none. */
  insets?: () => Insets;
  /** Called after every relayout, so `TouchPad` can move its buttons. */
  onLayout?: (metrics: ViewportMetrics) => void;
};

export class Viewport {
  /**
   * Parent of everything the game draws. Its children work in `viewWidth x 128` space;
   * this container carries the scale and the letterbox offset.
   */
  readonly root = new Container();

  /**
   * The 128x128 area inside `root`, offset by `contentOffsetX`. Every screen that is not
   * the widescreen play band should draw in here, which is what `StateMachine` does.
   */
  readonly screen = new Container();

  private readonly app: Application;

  private readonly options: ViewportOptions;

  private metrics: ViewportMetrics;

  private readonly onResize = (): void => {
    this.layout();
  };

  constructor(app: Application, options: ViewportOptions = {}) {
    this.app = app;
    this.options = options;
    this.screen.x = this.contentOffsetX;
    this.root.addChild(this.screen);
    this.app.stage.addChild(this.root);
    this.app.renderer.on('resize', this.onResize);
    this.metrics = this.measure();
    this.layout();
  }

  destroy(): void {
    this.app.renderer.off('resize', this.onResize);
    this.root.destroy({ children: true });
  }

  /** Current scale, offsets and pad regions. Read after `layout()`; see `toVirtual()`. */
  get current(): ViewportMetrics {
    return this.metrics;
  }

  /** How far the 128-wide UI is inset inside `root`. Non-zero only in widescreen. */
  get contentOffsetX(): number {
    return ((this.options.viewWidth ?? VIEW_WIDTH) - VIEW_WIDTH) / 2;
  }

  private measure(): ViewportMetrics {
    return computeLayout({
      cssWidth: this.app.screen.width,
      cssHeight: this.app.screen.height,
      resolution: this.app.renderer.resolution || 1,
      viewWidth: this.options.viewWidth,
      fit: this.options.fit,
      controls: this.options.controls,
      insets: this.options.insets?.(),
    });
  }

  /** Recompute the upscale for the renderer's current size. Idempotent. */
  layout(): void {
    this.metrics = this.measure();
    this.root.scale.set(this.metrics.scale);
    this.root.position.set(this.metrics.offsetX, this.metrics.offsetY);
    this.screen.x = this.contentOffsetX;
    this.options.onLayout?.(this.metrics);
  }

  /**
   * Map a `clientX`/`clientY` from a pointer or touch event into the drawn area's
   * coordinate space. Values outside the view mean the letterbox or the control band was
   * hit; callers decide whether to ignore them.
   */
  toVirtual(clientX: number, clientY: number): { x: number; y: number } {
    const { scale, offsetX, offsetY } = this.metrics;
    const rect = this.app.canvas.getBoundingClientRect();
    return {
      x: (clientX - rect.left - offsetX) / scale,
      y: (clientY - rect.top - offsetY) / scale,
    };
  }

  /** Map a client point into the canvas's own CSS-pixel space, where `TouchPad` works. */
  toCanvas(clientX: number, clientY: number): { x: number; y: number } {
    const rect = this.app.canvas.getBoundingClientRect();
    return { x: clientX - rect.left, y: clientY - rect.top };
  }
}
